  // ---- Toà nhà: bảng tầng ----
  'Toà nhà 5 tầng': { en: '5-floor building', zh: '5 层大楼', ja: '5 フロアのビル', ko: '5층 건물', es: 'Edificio de 5 plantas', fr: 'Bâtiment de 5 étages', de: 'Gebäude mit 5 Etagen', th: 'อาคาร 5 ชั้น', id: 'Gedung 5 lantai' },
  'Mỗi tầng nhận trọn một dự án. Hết tầng trống thì dự án mới xếp hàng.': { en: 'Each floor takes one whole project. When no floor is free, new projects wait in line.', zh: '每层负责一个完整项目。没有空闲楼层时，新项目将排队等待。', ja: '各フロアが 1 つのプロジェクトを丸ごと担当します。空きフロアがないと新しいプロジェクトは順番待ちになります。', ko: '각 층이 프로젝트 하나를 통째로 맡습니다. 빈 층이 없으면 새 프로젝트는 대기열에 들어갑니다.', es: 'Cada planta se encarga de un proyecto completo. Si no hay plantas libres, los proyectos nuevos esperan en cola.', fr: 'Chaque étage prend en charge un projet entier. S’il n’y a plus d’étage libre, les nouveaux projets attendent.', de: 'Jede Etage übernimmt ein ganzes Projekt. Ist keine Etage frei, warten neue Projekte in der Warteschlange.', th: 'แต่ละชั้นรับผิดชอบโปรเจกต์ทั้งโปรเจกต์ หากไม่มีชั้นว่าง โปรเจกต์ใหม่จะเข้าคิวรอ', id: 'Setiap lantai menangani satu proyek penuh. Jika tidak ada lantai kosong, proyek baru akan mengantre.' },
  'Trống': { en: 'Empty', zh: '空闲', ja: '空き', ko: '비어 있음', es: 'Libre', fr: 'Libre', de: 'Frei', th: 'ว่าง', id: 'Kosong' },
