  'Chọn phòng': { en: 'Choose department', zh: '选择部门', ja: '部署を選択', ko: '부서 선택', es: 'Elegir departamento', fr: 'Choisir un service', de: 'Abteilung wählen', th: 'เลือกแผนก', id: 'Pilih departemen' },
  'Việc mới → tầng đang rảnh ({free}/{total} tầng trống)': { en: 'New work → free floor ({free}/{total} free)', zh: '新工作 → 空闲楼层（{free}/{total} 层空闲）', ja: '新しい仕事 → 空きフロア（空き {free}/{total}）', ko: '새 작업 → 빈 층 (빈 층 {free}/{total})', es: 'Trabajo nuevo → planta libre ({free}/{total} libres)', fr: 'Nouveau travail → étage libre ({free}/{total} libres)', de: 'Neue Arbeit → freie Etage ({free}/{total} frei)', th: 'งานใหม่ → ชั้นที่ว่าง (ว่าง {free}/{total} ชั้น)', id: 'Pekerjaan baru → lantai kosong ({free}/{total} kosong)' },
  'Chỉ gửi được ảnh PNG, JPG, WEBP hoặc GIF.': { en: 'Only PNG, JPG, WEBP or GIF images can be sent.', zh: '只能发送 PNG、JPG、WEBP 或 GIF 图片。', ja: '送信できるのは PNG、JPG、WEBP、GIF 画像のみです。', ko: 'PNG, JPG, WEBP, GIF 이미지만 보낼 수 있습니다.', es: 'Solo se pueden enviar imágenes PNG, JPG, WEBP o GIF.', fr: 'Seules les images PNG, JPG, WEBP ou GIF peuvent être envoyées.', de: 'Nur PNG-, JPG-, WEBP- oder GIF-Bilder können gesendet werden.', th: 'ส่งได้เฉพาะรูป PNG, JPG, WEBP หรือ GIF', id: 'Hanya gambar PNG, JPG, WEBP, atau GIF yang bisa dikirim.' },
  'Ảnh lớn hơn 5 MB: {files}': { en: 'Images larger than 5 MB: {files}', zh: '超过 5 MB 的图片：{files}', ja: '5 MB を超える画像：{files}', ko: '5 MB를 넘는 이미지: {files}', es: 'Imágenes de más de 5 MB: {files}', fr: 'Images de plus de 5 MB : {files}', de: 'Bilder größer als 5 MB: {files}', th: 'รูปที่ใหญ่กว่า 5 MB: {files}', id: 'Gambar lebih dari 5 MB: {files}' },
  'Tối đa {n} ảnh mỗi tin nhắn.': { en: 'Up to {n} images per message.', zh: '每条消息最多 {n} 张图片。', ja: '1 メッセージにつき画像は最大 {n} 枚です。', ko: '메시지당 이미지는 최대 {n}장입니다.', es: 'Máximo {n} imágenes por mensaje.', fr: '{n} images maximum par message.', de: 'Höchstens {n} Bilder pro Nachricht.', th: 'สูงสุด {n} รูปต่อข้อความ', id: 'Maksimal {n} gambar per pesan.' },
  'Lỗi tải': { en: 'Upload failed', zh: '上传失败', ja: 'アップロード失敗', ko: '업로드 실패', es: 'Error al subir', fr: 'Échec de l’envoi', de: 'Upload fehlgeschlagen', th: 'อัปโหลดล้มเหลว', id: 'Gagal unggah' },
  'Bỏ ảnh {name}': { en: 'Remove image {name}', zh: '移除图片 {name}', ja: '画像 {name} を削除', ko: '이미지 {name} 제거', es: 'Quitar imagen {name}', fr: 'Retirer l’image {name}', de: 'Bild {name} entfernen', th: 'นำรูป {name} ออก', id: 'Hapus gambar {name}' },
  'Nội dung tin nhắn': { en: 'Message text', zh: '消息内容', ja: 'メッセージ本文', ko: '메시지 내용', es: 'Texto del mensaje', fr: 'Texte du message', de: 'Nachrichtentext', th: 'ข้อความ', id: 'Isi pesan' },
  'Đính kèm ảnh': { en: 'Attach images', zh: '附加图片', ja: '画像を添付', ko: '이미지 첨부', es: 'Adjuntar imágenes', fr: 'Joindre des images', de: 'Bilder anhängen', th: 'แนบรูป', id: 'Lampirkan gambar' },
  'Enter để gửi · Shift+Enter xuống dòng': { en: 'Enter to send · Shift+Enter for a new line', zh: 'Enter 发送 · Shift+Enter 换行', ja: 'Enter で送信 · Shift+Enter で改行', ko: 'Enter로 보내기 · Shift+Enter로 줄바꿈', es: 'Enter para enviar · Shift+Enter para nueva línea', fr: 'Entrée pour envoyer · Maj+Entrée pour aller à la ligne', de: 'Enter zum Senden · Umschalt+Enter für neue Zeile', th: 'Enter เพื่อส่ง · Shift+Enter เพื่อขึ้นบรรทัดใหม่', id: 'Enter untuk kirim · Shift+Enter untuk baris baru' },
  'Đang tải ảnh lên…': { en: 'Uploading images…', zh: '正在上传图片…', ja: '画像をアップロード中…', ko: '이미지 업로드 중…', es: 'Subiendo imágenes…', fr: 'Envoi des images…', de: 'Bilder werden hochgeladen…', th: 'กำลังอัปโหลดรูป…', id: 'Mengunggah gambar…' },
  'Thả ảnh vào đây để đính kèm': { en: 'Drop images here to attach', zh: '将图片拖放到此处以附加', ja: 'ここに画像をドロップして添付', ko: '여기에 이미지를 놓아 첨부', es: 'Suelta imágenes aquí para adjuntarlas', fr: 'Déposez des images ici pour les joindre', de: 'Bilder hier ablegen, um sie anzuhängen', th: 'วางรูปที่นี่เพื่อแนบ', id: 'Letakkan gambar di sini untuk melampirkan' },

